table = {0: (219, 600), 1: (2300, 14), 2: (90, 100), 3: (1327, 580)}

def translate(s, d):
    base, limit = table[s]
    if d < limit:
        return base + d
    return None

print(translate(2, 53))
for s, d in [(1, 500), (0, 1222), (3, 580)]:
    print(1 if translate(s, d) is None else 0)
